import { renderAvatar, portraitLayers } from './avatar.js';
import { PORTRAIT_LIBRARY, PORTRAIT_STAGES, portraitContext, availablePortraits, portraitEntry } from './portrait-library.js';
import { availableHeritages, heritageAllowsPortrait } from './heritages.js';

const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const labels={watch:'Knights & wardens',wanderer:'Cloaks & travelers',scholar:'Scholars & mages',healer:'Healers & pilgrims',craft:'Craftspeople',performer:'Bards & performers',court:'Court & finery',field:'Workers & countryfolk',young:'Young faces',elder:'Elder faces'};
const presentationLabels={masculine:'Masculine',feminine:'Feminine',androgynous:'Androgynous'};
export const PORTRAITS_PER_PAGE=24;
export function portraitGalleryPage(person,{age=27,state={},currentPerson=person}={}) {
  const requested=PORTRAIT_STAGES.find(p=>p.id===state.stage),previewAge=requested?requested.min:age,realContext=portraitContext(person,age),context=portraitContext(person,previewAge),current=portraitLayers(currentPerson,{age}).preset;
  const presentation=['masculine','feminine','androgynous'].includes(state.presentation)?state.presentation:'all';
  const archetype=Object.hasOwn(labels,state.archetype)?state.archetype:'all';
  const unlocked=availablePortraits(person,previewAge),all=PORTRAIT_LIBRARY.filter(p=>p.ancestry===context.ancestry&&p.stage===context.stage);
  let filtered=(state.showLocked?all:unlocked).filter(p=>(presentation==='all'||p.presentation===presentation)&&(archetype==='all'||p.archetype===archetype));
  const pages=Math.max(1,Math.ceil(filtered.length/PORTRAITS_PER_PAGE)),page=Math.max(0,Math.min(pages-1,Number.isInteger(state.page)?state.page:0));
  const key=current.key||PORTRAIT_LIBRARY.find(p=>p.src===current.src&&p.cell===current.cell)?.key;
  return {context,current,key,previewAge,realStage:realContext.stage,unlocked:unlocked.length,locked:all.length-unlocked.length,total:filtered.length,pages,page,presentation,archetype,
    currentVisible:filtered.some(p=>p.key===key),available:all.length,rows:filtered.slice(page*PORTRAITS_PER_PAGE,(page+1)*PORTRAITS_PER_PAGE)};
}
function preview(entry,age) {
  const profile=availableHeritages(entry.ancestry).find(h=>heritageAllowsPortrait(h,entry));
  const appearance={ancestry:entry.ancestry,heritage:profile.id,heritageVersion:1,portraitPresentation:entry.presentation,preset:entry.index>=0?'p'+String(entry.index).padStart(4,'0'):'legacy',portraitSelections:{[entry.stage]:entry.key}};
  return renderAvatar({appearance},{size:'large',age}).replace('decoding="async"','decoding="async" loading="lazy"');
}
export function findCurrentPortrait(person,{age=27}={}){
 const v=portraitGalleryPage(person,{age}),rows=availablePortraits(person,age),index=rows.findIndex(p=>p.key===v.key);
 return {page:index<0?0:Math.floor(index/PORTRAITS_PER_PAGE),presentation:'all',archetype:'all',showLocked:false,previewKey:null,message:index<0?'The current portrait is retained but is not a selectable entry in this stage’s gallery.':'Filters cleared. Your current portrait is shown; selection has not changed.'};
}
export function renderPortraitGallery(person,{age=27,state={},reason='',canChooseHeritage=false,currentPerson=person}={}) {
 const v=portraitGalleryPage(person,{age,state,currentPerson}),h=v.context.heritage,heritages=availableHeritages(v.context.ancestry),frozen=Boolean(reason),stage=PORTRAIT_STAGES.find(s=>s.id===v.context.stage);
 const candidate=portraitEntry(state.previewKey),allowedCandidate=candidate&&candidate.ancestry===v.context.ancestry&&candidate.stage===v.context.stage&&heritageAllowsPortrait(h,candidate)&&(!v.context.wolf||candidate.morphology==='canine');
 const choices=heritages.map(profile=>`<button type="button" class="portrait-heritage${profile.id===h.id?' is-selected':''}" data-op="gallery-heritage" data-id="${profile.id}" aria-pressed="${profile.id===h.id}"${!canChooseHeritage||v.context.wolf||frozen?' disabled':''}>${e(profile.name)}</button>`).join('');
 const stages=PORTRAIT_STAGES.map(p=>`<button type="button" data-op="gallery-stage" data-id="${p.id}" aria-pressed="${p.id===v.context.stage}" class="button ghost portrait-stage-filter"><strong>${p.label}</strong><small>${p.min}${p.max===null?'+':'–'+p.max} · ${p.id===v.realStage?'Your stage':'Preview only'}</small></button>`).join('');

 return `<div class="eyebrow">THE PORTRAIT BOOK · ${e(v.context.ancestry.toUpperCase())}</div><h2>Choose your portrait</h2><p class="portrait-gallery-intro">Browsing ${stage.label} portraits · ages ${stage.min}${stage.max===null?'+':'–'+stage.max}. Your character is ${Math.floor(age)}.${v.context.stage!==v.realStage?' Preview only; selecting requires your current life stage.':''} Paintings represent a life stage. Portrait presentation is independent of pronouns.</p><div class="portrait-gallery-header"><div class="portrait-gallery-current">${renderAvatar(currentPerson,{size:'large',age})}</div><div><span class="eyebrow">CURRENT PORTRAIT · BROWSING ${e(h.name)}</span><p>${e(h.description)}</p><p class="portrait-gallery-help">Browse freely. Preview a face, then use Select Portrait to apply it. Closing this book keeps your existing portrait and heritage.</p></div></div><div class="portrait-heritages" role="group" aria-label="Heritage to browse">${choices}</div><div class="portrait-age-locks" aria-label="Portrait age stages">${stages}</div>${reason?`<p class="notice" role="status">${e(reason)}</p>`:''}<div class="portrait-gallery-filters"><label>Presentation<select data-gallery-filter="presentation"><option value="all">All faces</option>${Object.entries(presentationLabels).map(([id,label])=>`<option value="${id}"${v.presentation===id?' selected':''}>${label}</option>`).join('')}</select></label><label>Collection<select data-gallery-filter="archetype"><option value="all">All collections</option>${[...new Set(PORTRAIT_LIBRARY.filter(p=>p.ancestry===v.context.ancestry&&p.stage===v.context.stage).map(p=>p.archetype))].map(id=>`<option value="${id}"${v.archetype===id?' selected':''}>${e(labels[id])}</option>`).join('')}</select></label><button type="button" class="button ghost small" data-op="gallery-locked" aria-pressed="${Boolean(state.showLocked)}">${state.showLocked?'Hide':'Show'} heritage locks (${v.locked})</button><button type="button" class="button ghost small" data-op="gallery-clear">Clear Filters</button><button type="button" class="button secondary small" data-op="gallery-current">Find Current Portrait</button></div><p class="portrait-gallery-count" role="status" aria-live="polite">${v.total} matching · ${v.unlocked} selectable for ${e(h.name)} · ${v.available} total in this ancestry and stage. ${v.total?`${v.page*PORTRAITS_PER_PAGE+1}–${Math.min(v.total,(v.page+1)*PORTRAITS_PER_PAGE)} shown`:'No portraits match these filters.'} · Page ${v.page+1} / ${v.pages}.${v.currentVisible?'':' Your current portrait is outside these filters; it remains selected.'} ${e(state.message||'')}</p>${allowedCandidate?`<section class="portrait-candidate" aria-labelledby="portrait-preview-heading"><div>${preview(candidate,v.previewAge)}</div><div><h3 id="portrait-preview-heading" tabindex="-1">Portrait preview</h3><p>${e(labels[candidate.archetype])} · ${e(presentationLabels[candidate.presentation])} · ${stage.label}</p><p>Illustrated equipment is part of the painting.</p><button type="button" class="button primary" data-op="gallery-select" data-id="${e(candidate.key)}"${frozen||v.context.stage!==v.realStage?' disabled':''}>Select Portrait</button><button type="button" class="button ghost" data-op="gallery-cancel-preview">Back to faces</button></div></section>`:''}<div class="portrait-gallery-grid" role="group" aria-label="Available illustrated portraits">${v.rows.map(p=>{
  const allowed=heritageAllowsPortrait(h,p)&&(!v.context.wolf||p.morphology==='canine'),selected=v.key===p.key,previewed=allowedCandidate&&candidate.key===p.key,unlock=availableHeritages(p.ancestry).filter(profile=>heritageAllowsPortrait(profile,p)).map(profile=>profile.name).join(' / '),caption=`${labels[p.archetype]} · ${(p.index>=0?p.index:p.cell)+1}`;
  return `<button type="button" class="portrait-choice${selected?' is-selected':''}${allowed?'':' is-locked'}" data-op="gallery-preview" data-id="${e(p.key)}" aria-label="${e(`${caption}, ${presentationLabels[p.presentation]}${selected?', current portrait':''}${allowed?'':', requires '+unlock}`)}" aria-pressed="${Boolean(previewed)}"${!allowed||frozen?' disabled':''}>${preview(p,v.previewAge)}<span class="portrait-choice-caption">${e(caption)}</span><small>${e(allowed?selected?'Current portrait':previewed?'Previewing':presentationLabels[p.presentation]:'Locked · '+unlock)}</small></button>`;
 }).join('')||'<p class="muted">Clear filters or choose another collection or presentation.</p>'}</div><div class="portrait-gallery-pagination"><button type="button" class="button secondary small" data-op="gallery-page" data-id="${v.page-1}"${v.page===0?' disabled':''}>‹ Previous</button><span>${v.page+1} / ${v.pages}</span><button type="button" class="button secondary small" data-op="gallery-page" data-id="${v.page+1}"${v.page+1===v.pages?' disabled':''}>Next ›</button></div><p class="portrait-gallery-help">Browse any stage without changing your character’s age. Only your current age stage can be selected. Your earlier saved portrait choices remain with this life.</p><div class="modal-buttons"><button type="button" class="button secondary" data-op="close-modal">Keep Current Portrait</button></div>`;
}
